  "welfare.gate": "g\\!\\left(x;\\,\\theta^-,\\theta^+\\right) \\;=\\; \\begin{cases} 0 & x < \\theta^-\\\\[2pt] 3t^2 - 2t^3 & \\theta^- \\le x < \\theta^+\\\\[2pt] 1 & x \\ge \\theta^+ \\end{cases}",
  "welfare.t": "t \\;=\\; \\frac{x - \\theta^-}{\\theta^+ - \\theta^-}",
  "welfare.incident": "I = \\max\\!\\left(0,\\ 1 - \\sum_{\\text{incidents}} \\text{severity}\\right) \\qquad S_1 = 1.0,\\quad S_2 = 0.4,\\quad S_3 = 0.1",
  "welfare.S": "S = \\min\\!\\left(U,\\, D_{\\text{eff}}\\right)",
